/// Returns the table entry for Z, or nullptr when Z is outside 1..118.
/// \param atomicNumber Z of the element to find.
/// \returns The table entry, or nullptr when Z is outside 1..118.
constexpr const ElementData* FindElement(int atomicNumber) noexcept {
    if (atomicNumber < 1 || atomicNumber > 118)
    {
        return nullptr;
    }

    return &kElements[static_cast<std::size_t>(atomicNumber - 1)];
}

/// Returns the table entry for an exact-case IUPAC symbol, or nullptr.
/// \param symbol IUPAC symbol (exact case).
/// \returns The table entry, or nullptr when the symbol is unknown.
constexpr const ElementData* FindElement(std::string_view symbol) noexcept {
    for (const auto& e : kElements)
    {
        if (e.symbol == symbol)
        {
            return &e;
        }
    }

    return nullptr;
}

